package com.lms.entity;import java.time.*;import jakarta.persistence.*;import lombok.*;@Entity @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class AuditLog{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String action; private Long performedBy; private LocalDateTime performedAt; @PrePersist void pre(){performedAt=LocalDateTime.now();}}